  "recipients": {
    "to": ["Security/Compliance"],
    "cc": ["john.smith@example.com"]
  },
  "operations_team": [
    {
      "name": "Alice Johnson",
      "email": "alice.johnson@example.com"
    },
    {
      "name": "Mark Lee",
      "email": "mark.lee@example.com"
